const ICONS = {
  home: '<path d="M3 11l9-8 9 8v9a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>',
  user: '<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 3.5-7 8-7s8 3 8 7"/>',
  settings: '<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>',
  leaf: '<path d="M5 19c0-9 5-14 15-14 0 10-5 15-14 15M5 19l7-7"/>',
  bolt: '<path d="M13 2L4 14h7l-1 8 9-12h-7z"/>',
  bars: '<path d="M5 21V10M12 21V4M19 21v-8"/>',
  trend: '<path d="M3 17l6-6 4 4 8-9"/>',
  back: '<path d="M20 12H4M10 6l-6 6 6 6"/>',
  setup: '<rect x="6" y="6" width="12" height="12" rx="1.5"/>',
  upload: '<path d="M12 19V5M6 11l6-6 6 6"/>',
  search: '<circle cx="11" cy="11" r="6"/><path d="M20 20l-4-4"/>',
  sigma: '<path d="M18 5H6l6 7-6 7h12"/>',
  check: '<path d="M5 13l4 4L19 7"/>',
  columns: '<rect x="4" y="5" width="16" height="14" rx="1.5"/><path d="M12 5v14"/>',
  report: '<rect x="4" y="5" width="16" height="14" rx="1.5"/><path d="M4 10h16M4 14h16"/>',
  list: '<path d="M5 7h14M5 12h14M5 17h14"/>'
};
const svg = (name, stroke = 'currentColor') => `<svg viewBox="0 0 24 24" fill="none" stroke="${stroke}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name] || ICONS.setup}</svg>`;
const $ = id => document.getElementById(id);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;'
})[c]);
let activeId = null;
function render(model) {
  if (!model) return;
  activeId = model.activeItem || activeId || model.items && model.items[0] && model.items[0].id;
  $('logo').textContent = model.logoText || '';
  $('title').textContent = model.title || '';
  $('subtitle').textContent = model.subtitle || '';
  $('sectionLabel').textContent = model.sectionLabel || '';
  $('back').innerHTML = `${svg('back')}<span>${esc(model.backLabel || 'Back')}</span>`;

  // Icon rail
  const rail = (model.rail || []).map(r => {
    if (r.type === 'divider') return '<div class="rail-divider"></div>';
    if (r.type === 'spacer') return '<div class="rail-spacer"></div>';
    return `<button class="rail-btn ${r.active ? 'active' : ''}" data-rail="${esc(r.id)}" title="${esc(r.label)}" aria-label="${esc(r.label)}" style="color:${esc(r.color || '')}">${svg(r.icon)}</button>`;
  }).join('');
  $('rail').innerHTML = `<div class="rail-avatar">${esc(model.avatarText || '')}</div>${rail}`;

  // Menu items
  $('items').innerHTML = (model.items || []).map(it => {
    const badge = it.badge ? `<span class="badge ${esc(it.badgeColor || 'red')}">${esc(it.badge)}</span>` : '';
    return `<li><button class="item ${it.id === activeId ? 'active' : ''}" data-id="${esc(it.id)}" ${it.id === activeId ? 'aria-current="page"' : ''}>
      <span class="ico">${svg(it.icon)}</span><span class="label">${esc(it.label)}</span>${badge}</button></li>`;
  }).join('');
}
document.addEventListener('click', e => {
  const item = e.target.closest('.item');
  const rail = e.target.closest('.rail-btn');
  const back = e.target.closest('#back');
  if (item) {
    activeId = item.dataset.id;
    document.querySelectorAll('.item').forEach(b => b.classList.toggle('active', b === item));
    appsmith.updateModel({
      selectedItem: activeId
    });
    appsmith.triggerEvent('onItemClick');
  } else if (rail) {
    appsmith.updateModel({
      selectedRail: rail.dataset.rail
    });
    appsmith.triggerEvent('onRailClick');
  } else if (back) {
    appsmith.triggerEvent('onBackClick');
  }
});
appsmith.onReady(() => {
  render(appsmith.model);
  appsmith.onModelChange(render);
});

